.detail-header { margin-bottom: 18px; }
.task-row { display: flex; align-items: center; gap: 12px; padding: 14px 16px; margin: 8px 0; background: white; border: 1px solid #dce2e9; border-radius: 6px; }
.task-row input { flex: initial; }

else app.innerHTML = `<div class="detail-header"><button id="back" type="button">Projects</button></div><h1>${escapeHtml(project.name)}</h1>
  <form id="task-form"><label for="task-title">Task title</label><input id="task-title" type="text" aria-label="Task title"><button type="submit">Create task</button></form>
  <div id="task-message" role="alert" hidden></div>
  <label for="task-filter">Task filter</label><select id="task-filter"><option>All</option><option>Open</option><option>Completed</option></select>
  <section id="task-list" aria-label="Tasks"></section>`;
app.querySelector('#back').addEventListener('click', () => { window.location.href = '/'; });
if (project) {
  const list = app.querySelector('#task-list');
  const refresh = async () => {
    const tasks = await fetch(`/api/projects/${encodeURIComponent(id)}/tasks`).then(response => response.json());
    const filter = app.querySelector('#task-filter').value;
    list.innerHTML = tasks.filter(task => filter === 'All' || (filter === 'Completed') === Boolean(task.completed)).map(task => `<div class="task-row" data-testid="task-row"><span>${escapeHtml(task.title)}</span><input type="checkbox" aria-label="Complete ${escapeHtml(task.title)}" data-task="${task.id}" ${task.completed ? 'checked' : ''}></div>`).join('');
    list.querySelectorAll('[data-task]').forEach(box => box.addEventListener('change', async () => {
      await fetch(`/api/projects/${encodeURIComponent(id)}/tasks/${box.dataset.task}`, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ completed: box.checked }) });
      await refresh();
    }));
  };
  app.querySelector('#task-filter').addEventListener('change', refresh);
  app.querySelector('#task-form').addEventListener('submit', async event => {
    event.preventDefault();
    const input = app.querySelector('#task-title'), message = app.querySelector('#task-message'), title = input.value.trim();
    if (!title) { message.textContent = 'Task title is required'; message.hidden = false; return; }
    const response = await fetch(`/api/projects/${encodeURIComponent(id)}/tasks`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ title }) });
    if (!response.ok) { message.textContent = 'Task title is required'; message.hidden = false; return; }
    message.hidden = true; input.value = ''; await refresh();
  });
  await refresh();
}

